() => {
  const b = document.querySelector('[data-testid="save-button"]');
  const results = {};
  const candidates = ['text-shadow-xs','text-shadow-2xs','text-shadow','text-shadow-md','text-shadow-[0_1px_2px_rgba(0,0,0,0.3)]'];
  const orig = 'px-4 py-2 rounded-md bg-blue-600 text-sm font-medium text-white';
  for (const c of candidates) {
    b.className = orig + ' ' + c;
    // force reflow
    void b.offsetHeight;
    results[c] = getComputedStyle(b).textShadow;
  }
  b.className = orig;
  return results;
}

