  const res = await fetch('http://127.0.0.1:8765/packages/barocss-browser/dist/cdn/barocss.js');
  const txt = await res.text();
  const found = new Set();
  const re = /["'`]([a-z-]*shadow[a-z-]*)["'`]/g;
  let m;
  while ((m = re.exec(txt))) found.add(m[1]);
  // also find staticUtility or registerUtility names
  const re2 = /(staticUtility|functionalUtility|registerUtility|createUtility)\s*\(\s*["'`]([^"'`]+)/g;
  const utils = [];
  while ((m = re2.exec(txt)) && utils.length < 400) utils.push(m[2]);
  return {shadowStrings: [...found], utilsWithShadow: utils.filter(u=>/shadow/.test(u))};
}

