async () => {
  const mod = await import('/packages/barocss-browser/dist/cdn/barocss.js');
  const keys = Object.keys(mod);
  // Try to find a registry of utilities
  let utilNames = null;
  try {
    for (const k of keys) {
      const v = mod[k];
      if (v && typeof v === 'object' && (v.utilities || v.staticUtilities)) {
        utilNames = Object.keys(v.utilities || v.staticUtilities);
      }
    }
  } catch(e) {}
  return { exports: keys, utilNames };
}

